import{_ as t,o as i,c as n,a2 as a}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Analytics, intelligence, options, predictions, and tax","description":"Purpose, data limitations, source freshness, and decision-support framing for each analytical surface.","frontmatter":{"title":"Analytics, intelligence, options, predictions, and tax","description":"Purpose, data limitations, source freshness, and decision-support framing for each analytical surface.","audience":"user","status":"current","last_verified":"2026-07-19T00:00:00.000Z"},"headers":[],"relativePath":"use-zenin/analytics-intelligence-options-predictions-tax.md","filePath":"use-zenin/analytics-intelligence-options-predictions-tax.md","lastUpdated":null}'),s={name:"use-zenin/analytics-intelligence-options-predictions-tax.md"};function o(r,e,c,d,l,p){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="analytics-intelligence-options-predictions-and-tax" tabindex="-1">Analytics, intelligence, options, predictions, and tax</h1><p>These surfaces help you interpret context. They are <strong>decision-support</strong>, not decisions.</p><h2 id="analytics" tabindex="-1">Analytics</h2><p>Review performance, exposure, and cross-market analytics. Use it to spot patterns in your own recorded activity and holdings.</p><p><strong>Limitations:</strong> analytics depend on the data you have connected and recorded. Thin or missing history limits what can be computed.</p><h2 id="intelligence" tabindex="-1">Intelligence</h2><p>Intelligence views bring together event timelines, transmission paths, affected holdings, market signals, macro regime context, and research queues.</p><p><strong>Limitations:</strong> signal and event coverage vary by country, instrument, and provider. Some items are reference-only.</p><h2 id="options" tabindex="-1">Options</h2><p>Explore options chains, Greeks, calculators, strategy simulators, and whale-trade views.</p><p><strong>Limitations:</strong> chain, Greek, and trade-tape coverage vary by venue and provider. Strategy probabilities are model outputs, not guarantees.</p><h2 id="predictions" tabindex="-1">Predictions</h2><p>Prediction-market snapshots (for example, Polymarket-based) show sentiment as priced by a market.</p><p><strong>Limitations:</strong> prediction signals are informational. They reflect a market&#39;s pricing, not Zenin&#39;s view, and may not reflect your complete circumstances.</p><h2 id="tax" tabindex="-1">Tax</h2><p>Indicative tax-estimation workflows estimate scenarios from your recorded activity.</p><p><strong>Limitations:</strong> tax estimates are <strong>informational only</strong> and may not reflect your jurisdiction, filing status, or complete circumstances. They are not tax advice.</p><h2 id="decision-support-framing" tabindex="-1">Decision-support framing</h2><p>For every analytical surface:</p><ul><li>Treat outputs as <strong>input to your judgment</strong>, not a recommendation.</li><li>Check the freshness state of the underlying data.</li><li>Remember that strategy probabilities, tax estimates, and prediction signals require independent review.</li></ul><hr><h2 id="what-this-does-does-not-do" tabindex="-1">What this does / does not do</h2><p><strong>What this does</strong></p><ul><li>Surfaces analytics, intelligence, options, prediction, and tax context in one workspace.</li><li>Marks data limitations and freshness where coverage is partial.</li></ul><p><strong>What it does not do</strong></p><ul><li>It does not give investment, tax, or financial advice.</li><li>It does not guarantee the accuracy of model or prediction outputs.</li><li>It does not file taxes or execute trades.</li></ul><p><strong>Data source and freshness</strong></p><p>These surfaces combine your workspace data (holdings, trades, journal) with configured providers (market data, macro, options venues, prediction markets). Coverage and freshness vary by instrument, venue, and provider.</p>',28)])])}const g=t(s,[["render",o]]);export{m as __pageData,g as default};
